// Main Campus building locations, sourced from the University of Ottawa's own
// public campus map page (uottawa.ca/about-us/administration-services/
// facilities/campus-maps), which embeds this exact lat/lng + code + name +
// address dataset in the page for its own Leaflet map. Pulled once and
// hardcoded here rather than fetched at runtime, since it changes rarely and
// this avoids a live dependency on a third-party page's internal data
// structure.
//
// Building footprint outlines ("polygons") are separately sourced from
// OpenStreetMap (via the Overpass API, © OpenStreetMap contributors, ODbL -
// see https://www.openstreetmap.org/copyright), matched to each building by
// exact name, then address, then closest nearby footprint (in that priority
// order, each within a sanity distance so a same-named-street collision
// can't silently steal the wrong building's shape). A building can have more
// than one ring: a handful of buildings have real extensions OSM mapped as
// separate untagged fragments, so those get swept in (only when they
// directly touch the matched shape and carry no name of their own, so two
// different NAMED buildings can never merge together). Not every building
// has a matching OSM footprint - those fall back to a point marker (see
// CampusMapSection); 1 Nicholas (NCL) and 110 Séraphin-Marion have no
// confident match at all, so they use the closest nearby footprint as a
// best-effort approximation instead.
//
// Excludes the Roger Guindon, 99 Bank (Telfer Executive Campus), and Kanata
// North campuses - Main Campus and Lees Campus only, per the dashboard's
// scope.
export interface CampusBuilding {
  code: string
  name: string
  address: string
  position: [number, number]
  polygons: [number, number][][] | null
}

